package ca.humber.alerts;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import jakarta.validation.Valid;import java.util.*;@RestController @RequestMapping("/api/alerts") public class AlertController {private final AlertRepository repo;public AlertController(AlertRepository r){repo=r;}@GetMapping public List<Alert> all(){return repo.findAll();}@GetMapping("/{id}")public ResponseEntity<Alert> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}@GetMapping("/search")public List<Alert> search(@RequestParam(required=false)String severity,@RequestParam(required=false)String status){if(severity!=null&&status!=null)return repo.findBySeverityAndStatus(severity,status);if(severity!=null)return repo.findBySeverity(severity);if(status!=null)return repo.findByStatus(status);return repo.findAll();}@PostMapping public ResponseEntity<Alert> create(@Valid @RequestBody Alert alert){alert.id=null;alert.createdAt=java.time.LocalDateTime.now();return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(alert));}@PutMapping("/{id}")public ResponseEntity<Alert> update(@PathVariable Long id,@Valid @RequestBody Alert incoming){return repo.findById(id).map(a->{a.message=incoming.message;a.severity=incoming.severity;a.status=incoming.status;return ResponseEntity.ok(repo.save(a));}).orElse(ResponseEntity.notFound().build());}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();}}